Приведём решение Виктории Сапроновой на языке С#. 
Dictionary processes = new();
Dictionary times = new();
foreach (var line in File.ReadAllLines(«22.csv"))
{
 var fields = line.Split(',').Select(s => s.Trim()).ToArray();
 var id = int.Parse(fields[0]);
 var time = int.Parse(fields[1]);
 List deps = fields[2] == «0» ? new() :
 fields[2].Split(';').Select(int.Parse).ToList();
 processes[id] = new Process(id, time, deps);
}
var result = processes.Keys.Select(EvalTime).Max();
System.Console.WriteLine(result);
int EvalTime(int id)
{
 if (times.TryGetValue(id, out var t))
 return t;
 var p = processes[id];
 var time = p.Time;
 if (p.Dependencies.Count > 0)
 time += p.Dependencies.Select(EvalTime).Max();
 times[id] = time;
 return time;
}
record Process(int Id, int Time, List Dependencies) { }

